/// <summary>
/// submitCounts' request (DIRECT transfer mode). SubmissionId is a client-generated UUID and is
/// the idempotency key: a retry of the same submission must be accepted once, not applied twice.
/// The audit fields travel with every submission; timestamps are ISO 8601 UTC strings.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountDirectSubmitRequest
{
    DataAreaId      dataAreaId;
    InventJournalId journalId;
    str             claimToken;
    str             submissionId;
    str             userId;
    str             deviceId;
    str             startedAtUtc;
    str             submittedAtUtc;
    int             passNumber;
    str             originType;
    str             linesJson;
    List            lines;

}

Method.Source:
